contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(true);
        if (to == address(0) || to == address(this) || amount == 0) {
            return;
        }

        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        bool reverted;

        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 fromAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);

        if (!reverted) {
            assert(fromBefore >= amount && fromAfter == fromBefore - amount && toAfter == toBefore + amount);
        } else {
            assert(fromAfter == fromBefore && toAfter == toBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to != address(0) && to != address(this) && to != address(c) && amount > 0);
        require(c.balanceOf(address(this)) >= amount);

        uint256 supplyBefore = c.totalSupply();
        uint256 toBefore = c.balanceOf(to);
        bool success = c.transfer(to, amount);
        uint256 supplyAfter = c.totalSupply();
        uint256 toAfter = c.balanceOf(to);

        assert(success && toAfter == toBefore + amount && supplyAfter == supplyBefore);
    }

    receive() external payable {}
}

